import java.util.ArrayList;
import java.util.List;

public class Permutation {
    public static List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<List<Integer>>();
        if (nums == null || nums.length == 0) {
            return result;
        }
        List<Integer> comb = new ArrayList<Integer>();
        for (int i = 0; i < nums.length; i++) {
            comb.add(nums[i]);
            List<List<Integer>> nextCombs = permute(nums, i + 1, nums.length - 1);
            for (List<Integer> nextComb : nextCombs) {
                result.add(comb);
                result.add(nextComb);
            }
            comb.remove(comb.size() - 1);
        }
        return result;
    }

    private static List<List<Integer>> permute(int[] nums, int start, int end) {
        List<List<Integer>> result = new ArrayList<List<Integer>>();
        if (start == end) {
            List<Integer> comb = new ArrayList<Integer>();
            for (int i = start; i <= end; i++) {
                comb.add(nums[i]);
            }
            result.add(comb);
        } else {
            for (int i = start; i <= end; i++) {
                swap(nums, start, i);
                List<List<Integer>> nextCombs = permute(nums, start + 1, end);
                for (List<Integer> nextComb : nextCombs) {
                    result.add(nextComb);
                }
                swap(nums, start, i);
            }
        }
        return result;
    }

    private static void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}
