            if (!visited[neighbor[0]][neighbor[1]]) {
                visited[neighbor[0]][neighbor[1]] = true;
                queue.add(neighbor);
            }
        }
    }
    // If the queue is empty and the ending n-tersection is not visited, return "cannot be travelled"
    return "cannot be travelled";
}

// Helper method to get all neighbors of a n-tersection
public static int[][] getNeighbors(int[] current, int[][] paths) {
    // Initialize an array to store the neighbors
    List<int[]> neighbors = new ArrayList<>();
    // Loop through all paths
    for (int[] path : paths) {
        // If the current n-tersection is the starting point of a path, add the ending point of the path as a neighbor
        if (Arrays.equals(current, path[0])) {
            neighbors.add(path[1]);
        }
        // If the current n-tersection is the ending point of a path, add the starting point of the path as a neighbor
        if (Arrays.equals(current, path[1])) {
            neighbors.add(path[0]);
        }
    }
    // Return an array of neighboring n-tersections
    return neighbors.toArray(new int[neighbors.size()][]);
}
