public class SearchRotatedArray {

    public static int search(int[] nums, int target) {
        // Special case: Empty array
        if (nums.length == 0) {
            return -1;
        }

        // Get the pivot index
        int pivot = findPivot(nums);

        // Binary search on the left and right subarrays
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int midVal = nums[mid];

            int compare = midVal - target;
            if (compare == 0) {
                return mid;
            } else if (compare < 0) {
                if (mid < pivot) {
                    // Search the right subarray
                    left = mid + 1;
                } else {
                    // Search the left subarray
                    right = mid - 1;
                }
            } else {
                if (mid > pivot) {
                    // Search the left subarray
                    right = mid - 1;
                } else {
                    // Search the right subarray
                    left = mid + 1;
                }
            }
        }

        // Target not found
        return -1;
    }

    public static int findPivot(int[] nums) {
        for (int i = 0; i < nums.length - 1; i++) {
            if (nums[i] > nums[i + 1]) {
                return i;
            }
        }

        return nums.length - 1;
    }
}

