    // of the sorted array
    for (int i = 0; i < numToRemove; i++) {
        arr[i] = arr[numToRemove + 1];
        arr[arr.length - 1 - i] = arr[arr.length - numToRemove - 1];
    }

    // Calculate the trimmed mean
    mean = 0.0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

