  for (int i = 0; i < n; i++) {
    time[i] = Integer.MAX_VALUE;
  }

  // Set the time for node 0 to 0
  time[0] = 0;

  // Traverse the graph using DFS
  for (int i = 0; i < n; i++) {
    if (time[i] == Integer.MAX_VALUE) {
      continue;
    }

    // Traverse the neighbors of the current node
    for (int j = 0; j < edges[i].length; j++) {
      int neighbor = edges[i][j];

      // If the neighbor has an apple, update the time for the current node
      if (hasApple[neighbor]) {
        time[i] = Math.min(time[i], time[neighbor] + 1);
      }

      // If the neighbor does not have an apple, update the time for the current node
      else {
        time[i] = Math.min(time[i], time[neighbor]);
      }
    }
  }

  // Return the minimum time required to collect all the apples and return to node 0
  return time[0];
