public int kthFactor(int n, int k) {
    // Find the prime factorization of n
    Map<Integer, Integer> primeFactors = primeFactorization(n);

    // Initialize a variable to keep track of the number of factors found so far
    int count = 1;

    // Iterate through the prime factors and their exponents
    for (Map.Entry<Integer, Integer> entry : primeFactors.entrySet()) {
        int prime = entry.getKey();
        int exponent = entry.getValue();

        // Calculate the number of factors contributed by the current factor
        int numFactors = primeToTheKth(prime, k);

        // Update the count
        count += numFactors;

        // Check if we have found the kth factor
        if (count == k) {
            return prime;
        }
    }

    // If we have iterated through all the prime factors and the count is still less than k, return -1
    return -1;
}

