public int primeToTheKth(int prime, int k) {
    return (int) Math.pow(prime, k - 1);
}

// Function to find the prime factorization of a positive integer n
public Map<Integer, Integer> primeFactorization(int n) {
    Map<Integer, Integer> primeFactors = new HashMap<>();

    // Iterate from 2 to the square root of n
    for (int i = 2; i <= Math.sqrt(n); i++) {
        // If n is divisible by i, i is a prime factor of n
        if (n % i == 0) {
            // Add the prime factor and its exponent to the map
            int exponent = 0;
            while (n % i == 0) {
                n /= i;
                exponent++;
            }
            primeFactors.put(i, exponent);
        }
    }

    // If n is a prime number, it will not have any prime factors except for itself
    if (n > 1) {
        primeFactors.put(n, 1);
    }

    return primeFactors;
}
