    /**
     * Find the closest M numbers to the target value in a sorted list. A time
     * complexity of O(log M) is guaranteed.
     *
     * @param list  The sorted list of integers.
     * @param M  The target number.
     * @param k  The number of closest elements to find.
     * @return A list of the k closest elements to the target value.
     */
    public List<Integer> closestNumbers(int[] list, int M, int k) {
        int left = 0;
        int right = list.length - 1;
        while (left < right) {
            int mid = (left + right) / 2;
            if (list[mid] < M) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        int start = Math.max(0, left - k);
        int end = Math.min(right + k, list.length - 1);
        List<Integer> result = new ArrayList<>();
        for (int i = start; i < end; i++) {
            result.add(list[i]);
        }
        return result;
    }

